const fs = require('fs');
const path = require('path');

const kristenQuestions = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'generators', 'agama_kristen.json'), 'utf8'));
const seenQuestions = new Set(kristenQuestions.map(q => q.question));

function addQ(grade, difficulty, topic, question, options, correctAnswer, explanation) {
  if (seenQuestions.has(question)) {
    throw new Error(`Duplicate Kristen question found: "${question}"`);
  }
  seenQuestions.add(question);

  const diffCode = difficulty === 'mudah' ? 'm' : (difficulty === 'sedang' ? 's' : 'u');
  const index = kristenQuestions.filter(q => q.grade === grade && q.difficulty === difficulty).length + 1;
  const id = `aga-kristen-k${grade}-${diffCode}${String(index).padStart(2, '0')}`;

  kristenQuestions.push({
    id,
    grade,
    subject: 'pendidikan-agama',
    religion: 'kristen',
    difficulty,
    topic,
    question,
    options,
    correctAnswer,
    explanation
  });
}

addQ(2, 'mudah', 'Hukum Taurat Kelima', 'Hukum Taurat yang kelima berisi perintah Tuhan untuk ...', ['Jangan mencuri', 'Hormatilah ayahmu dan ibumu', 'Jangan berbohong', 'Kuduskanlah hari Sabat'], 1, 'Hukum ke-5 memerintahkan anak untuk menghormati orang tua.');
addQ(2, 'mudah', 'Janji Allah Pelangi', 'Tanda pelangi di awan yang diberikan Allah kepada Nabi Nuh melambangkan ...', ['Janji Allah tidak akan memusnahkan bumi lagi dengan air bah', 'Akan datangnya hujan emas', 'Tanda dimulainya perang', 'Peringatan badai petir'], 0, 'Pelangi adalah tanda perjanjian kasih setia Allah kepada seluruh makhluk bumi.');
addQ(2, 'mudah', 'Mukjizat Lima Roti', 'Tuhan Yesus memberi makan lima ribu orang laki-laki dengan menggunakan bekal seorang anak kecil berupa ...', ['Dua roti dan lima ikan', 'Lima roti jelai dan dua ekor ikan kecil', 'Tujuh roti gandum dan madu', 'Sepuluh ketupat dan daging'], 1, 'Yesus melipatgandakan 5 roti jelai dan 2 ikan kecil hingga mencukupi 5.000 orang bahkan bersisa 12 bakul.');
addQ(2, 'mudah', 'Keramahan', 'Sikap ramah terhadap teman di sekolah dicontohkan dengan selalu ...', ['Membentak teman yang lambat', 'Menyapa dengan senyum dan tutur kata sopan', 'Menolak duduk bersama anak baru', 'Membuang muka saat berpapasan'], 1, 'Senyum dan tegur sapa ramah mencerminkan kehangatan kasih Kristus.');
addQ(2, 'mudah', 'Kisah Samuel', 'Anak laki-laki yang sejak kecil setia melayani Tuhan di Bait Allah di bawah bimbingan Imam Eli bernama ...', ['Daud', 'Samuel', 'Yusuf', 'Salomo'], 1, 'Samuel diserahkan oleh ibunya Hana untuk melayani Tuhan di rumah Allah.');
addQ(2, 'mudah', 'Bahtera Nuh Merpati', 'Burung yang dilepaskan Nabi Nuh dari jendela bahtera dan kembali membawa sehelai daun zaitun segar adalah burung ...', ['Gagak', 'Merpati', 'Rajawali', 'Pipit'], 1, 'Burung merpati membawa ranting zaitun menandakan air bah telah surut dan tanaman mulai bertunas.');
addQ(2, 'mudah', 'Doa Bapa Kami Awal', 'Kalimat pembuka dalam Doa Bapa Kami berbunyi: "Bapa kami yang di ..."', ['Gereja', 'Surga, dikuduskanlah nama-Mu', 'Bumi yang indah', 'Gunung yang tinggi'], 1, 'Doa Bapa Kami diawali pengakuan: "Bapa kami yang di surga, dikuduskanlah nama-Mu".');
addQ(2, 'mudah', 'Tetangga', 'Orang yang tinggal bersebelahan atau dekat dengan rumah kita disebut ...', ['Tetangga', 'Musuh', 'Pelayan', 'Orang asing'], 0, 'Tetangga adalah sesama terdekat yang wajib kita kasihi dan perlakukan dengan baik.');
addQ(2, 'mudah', 'Syukur Makanan', 'Cara terbaik mengungkapkan rasa terima kasih kepada Tuhan atas rezeki makanan setiap hari adalah ...', ['Menyisakan banyak nasi di piring', 'Berdoa mengucap syukur sebelum dan sesudah makan', 'Mengeluh jika menunya sederhana', 'Membuang sayuran ke selokan'], 1, 'Berdoa dengan tulus sebelum menyantap hidangan adalah ungkapan syukur kepada Sang Pemberi Berkat.');
addQ(2, 'mudah', 'Tertib Ibadah', 'Perilaku tertib saat beribadah di gereja ditunjukkan dengan ...', ['Bermain game di ponsel dengan suara keras', 'Duduk manis, mendengarkan khotbah, dan ikut memuji Tuhan', 'Berlari di lorong kursi gereja', 'Makan camilan sambil bernyanyi'], 1, 'Sikap tenang dan tertib mencerminkan rasa hormat kepada hadirat Tuhan.');

addQ(2, 'sedang', 'Dua Loh Batu', 'Sepuluh Hukum Allah (Dasa Titah) dituliskan Allah pada dua loh batu di atas Gunung ...', ['Sinai / Horeb', 'Karmel', 'Zaitun', 'Nebo'], 0, 'Hukum Taurat diserahkan Allah kepada Nabi Musa di atas Gunung Sinai.');
addQ(2, 'sedang', 'Menghibur Teman', 'Bila melihat kawan sekelas menangis tersedu-sedu karena pensil warnanya hilang, tindakan kasih kita adalah ...', ['Menyorakinya agar menangis lebih keras', 'Menghiburnya dan meminjamkan pensil warna kita kepadanya', 'Memarahinya karena ceroboh', 'Pergi meninggalkannya sendirian'], 1, 'Menghibur dan berbagi peralatan adalah cerminan anak yang berbelas kasih.');
addQ(2, 'sedang', 'Makanan Secukupnya', 'Dalam Doa Bapa Kami terdapat permohonan: "Berikanlah kami pada hari ini makanan kami yang ..."', ['Paling mewah dan mahal', 'Secukupnya', 'Bisa disimpan sampai tahun depan', 'Berlimpah ruah tanpa batas'], 1, 'Permohonan "makanan secukupnya" mengajarkan kebersahajaan dan ketergantungan harian pada pemeliharaan Allah.');
addQ(2, 'sedang', 'Penyakit Iri Hati', 'Perbuatan Kain yang tega memukul dan membunuh adiknya Habel berakar dari penyakit hati yaitu ...', ['Rasa takut pada singa', 'Iri hati dan sakit hati karena persembahannya ditolak', 'Keinginan membeli ladang baru', 'Kesalahpahaman soal gembala domba'], 1, 'Iri hati yang dibiarkan bertumbuh dalam hati Kain melahirkan dosa kemarahan dan pembunuhan.');
addQ(2, 'sedang', 'Hari Pentakosta', 'Tanda fisik yang menyertai turunnya Roh Kudus kepada para rasul di Yerusalem pada hari Pentakosta adalah ...', ['Gempa bumi yang meruntuhkan kota', 'Tiupan angin keras dan lidah-lidah seperti nyala api yang hinggap di atas kepala mereka', 'Hujan salju lebat di musim panas', 'Bintang berekor yang jatuh di atap rumah'], 1, 'Roh Kudus turun dalam rupa tiupan angin laksana badai dan lidah-lidah nyala api (Kisah Para Rasul 2).');
addQ(2, 'sedang', 'Rukun Bersaudara', 'Salah satu cara menciptakan kerukunan antara adik dan kakak di rumah adalah ...', ['Berebut gawai sampai menangis', 'Saling mengalah, meminjamkan mainan, dan saling menolong tugas rumah', 'Menyalahkan adik setiap kali ada barang rusak', 'Mengurung diri di dalam kamar'], 1, 'Rukun bersaudara membawa berkat dan sukacita bagi seluruh isi rumah tangga.');
addQ(2, 'sedang', 'Kisah Kesetiaan Rut', 'Perempuan Moab yang menunjukkan kesetiaan luar biasa mendampingi ibu mertuanya Naomi kembali ke Betlehem adalah ...', ['Orpa', 'Rut', 'Delila', 'Isebela'], 1, 'Rut berkata kepada Naomi: "Ke mana engkau pergi, ke situ jugalah aku pergi, dan bangsa-mulah bangsaku, dan Allahmulah Allahku."');
addQ(2, 'sedang', 'Doa Pagi', 'Bangun di pagi hari dengan tubuh yang sehat adalah bukti bahwa pemeliharaan Tuhan selalu ...', ['Terlambat datang', 'Baru setiap pagi dan besar kesetiaan-Nya', 'Hanya untuk anak-anak kaya', 'Berhenti ketika malam tiba'], 1, 'Ratapan 3:23 menegaskan kasih setia TUHAN tak berkesudahan, selalu baru setiap pagi.');
addQ(2, 'sedang', 'Kantin Kejujuran', 'Saat berbelanja di kantin kejujuran sekolah yang tidak ada penjaganya, seorang anak Tuhan akan ...', ['Mengambil makanan sebanyak-banyaknya tanpa membayar', 'Membayar uang pas ke dalam kotak uang sesuai harga barang', 'Mengambil uang kembalian lebih banyak dari yang seharusnya', 'Menyuruh teman mencuri kue'], 1, 'Integritas diuji saat tidak ada orang lain yang melihat selain Tuhan.');
addQ(2, 'sedang', 'Yesus Membasuh Kaki', 'Tindakan Tuhan Yesus membasuh kaki para murid-Nya pada malam perjamuan terakhir mengajarkan nilai ...', ['Siapa yang terkuat berhak berkuasa', 'Kerendahan hati dan kesediaan saling melayani dengan kasih', 'Mencuci kaki hanya tradisi pesta makan', 'Para murid harus memberi upah uang kepada guru'], 1, 'Yesus memberikan teladan agar sesama orang percaya saling melayani dalam kerendahan hati.');
addQ(2, 'sedang', 'Ibunda Samuel', 'Ibu dari nabi Samuel yang dengan tekun dan mencurahkan isi hatinya berdoa di Kemah Suci memohon anak adalah ...', ['Sara', 'Hana', 'Ribka', 'Rahel'], 1, 'Hana berdoa dengan cucuran air mata di Silo memohon seorang putra yang kemudian dipersembahkan bagi Tuhan.');
addQ(2, 'sedang', 'Sepuluh Orang Kusta', 'Dari sepuluh orang kusta yang disembuhkan oleh Tuhan Yesus di perbatasan Samaria dan Galilea, berapa orang yang kembali bersujud mengucap syukur?', ['Semua sepuluh orang', 'Hanya satu orang (orang Samaria)', 'Lima orang saja', 'Tidak ada satu pun'], 1, 'Hanya satu orang kusta yang kembali memuliakan Allah dan berterima kasih kepada Yesus (Lukas 17:15).');
addQ(2, 'sedang', 'Kesetiaan Janji Allah', 'Setiap kali melihat pelangi di langit setelah hujan reda, kita diingatkan bahwa Allah adalah Allah yang ...', ['Mudah berubah pikiran', 'Setia memegang janji-Nya kepada umat manusia sepanjang masa', 'Suka menghukum manusia tanpa alasan', 'Tinggal jauh di balik matahari'], 1, 'Pelangi adalah meterai kesetiaan perjanjian anugerah Allah yang tidak pernah luntur.');
addQ(2, 'sedang', 'Gotong Royong Kelas', 'Melaksanakan tugas piket kebersihan kelas bersama teman-teman dengan penuh sukacita merupakan bentuk pengamalan ...', ['Kerja paksa dari kepala sekolah', 'Tolong-menolong dan menjaga keindahan lingkungan belajar', 'Pamer kekuatan fisik', 'Membuang waktu jam istirahat'], 1, 'Piket bersama melatih kerja sama dan kepedulian terhadap kebersihan lingkungan.');
addQ(2, 'sedang', 'Didikan Amsal', 'Kitab Amsal mengajarkan bahwa anak yang bijak akan mendengarkan ...', ['Bujukan teman berbuat nakal', 'Didikan dan teguran orang tua demi kebaikan hidupnya', 'Gosip yang beredar di media sosial', 'Keinginan hawa nafsu sendiri'], 1, 'Mendengarkan didikan orang tua adalah jalan hikmat yang menuntun pada kehidupan berkat.');
addQ(2, 'sedang', 'Toleransi Hari Raya', 'Ketika teman kita yang beragama lain sedang merayakan hari rayanya dengan penuh khidmat, sikap kita adalah ...', ['Menyalakan musik kencang di depan rumahnya', 'Menghormati kekhusyukan mereka dan ikut menjaga ketertiban lingkungan', 'Mengajak mereka bermain bola di jalan umum', 'Mengejek pakaian adat yang mereka kenakan'], 1, 'Menghargai peribadatan sesama anak bangsa memelihara persatuan dan kerukunan NKRI.');
addQ(2, 'sedang', 'Penguasa Hari', 'Matahari diciptakan Allah untuk menguasai siang hari, sedangkan bulan dan bintang diciptakan untuk ...', ['Menguasai malam hari', 'Menakut-nakuti orang yang berjalan di jalan', 'Membuat bumi menjadi dingin membeku', 'Menghilangkan seluruh pepohonan'], 0, 'Kitab Kejadian menjelaskan benda penerang diciptakan untuk memisahkan siang dan malam.');
addQ(2, 'sedang', 'Menerima Nasihat', 'Bila bapak atau ibu kita menegur kesalahan kita di rumah, sikap anak yang berkarakter kristiani adalah ...', ['Membanting pintu kamar dan berteriak', 'Mendengarkan dengan rendah hati, mengakui kesalahan, dan memperbaikinya', 'Mogok tidak mau makan selama tiga hari', 'Menyalahkan adik atau kakak'], 1, 'Teguran orang tua dilandasi kasih sayang agar kita bertumbuh menjadi pribadi berhikmat.');
addQ(2, 'sedang', 'Menjaga Barang Pinjaman', 'Ketika meminjam buku cerita dari perpustakaan sekolah, sikap tanggung jawab yang benar adalah ...', ['Melipat dan mencoret-coret halamannya', 'Membaca dengan hati-hati dan mengembalikannya tepat waktu dalam kondisi rapi', 'Menghilangkan buku tersebut dan pura-pura lupa', 'Merobek gambar yang kita sukai untuk dibawa pulang'], 1, 'Menjaga keutuhan barang pinjaman adalah wujud kejujuran dan amanah moral.');
addQ(2, 'sedang', 'Kasih Persaudaraan', 'Mazmur 133 melukiskan sungguh alangkah baiknya dan indahnya apabila saudara-saudara diam bersama dengan ...', ['Bertengkar setiap sore', 'Rukun', 'Saling mendiamkan tanpa senyum', 'Memperebutkan warisan'], 1, 'Mazmur 133: "Sungguh alangkah baiknya dan indahnya apabila saudara-saudara diam bersama dengan rukun!"');

addQ(2, 'sulit', 'Tafsir Jadilah Kehendak-Mu', 'Dalam Doa Bapa Kami kita mengucapkan: "Jadilah kehendak-Mu di bumi seperti di surga". Sikap batin yang diajarkan dalam kalimat ini adalah ...', ['Memaksa Tuhan menuruti seluruh keinginan pribadi kita', 'Kesiapan hati untuk menundukkan kemauan diri sendiri di bawah rencana dan ketetapan terbaik Allah', 'Pasrah tanpa mau belajar dan berusaha', 'Menganggap surga tidak ada hubungannya dengan bumi'], 1, 'Doa ini melatih penyerahan diri secara iman bahwa kehendak Allah selalu yang terbaik dan sempurna bagi hidup kita.');
addQ(2, 'sulit', 'Analisis Lima Roti', 'Apa pelajaran moral dan rohani terbesar dari kerelaan anak kecil yang memberikan 5 roti jelai dan 2 ikan kepada murid Yesus?', ['Anak itu tidak lapar sehingga memberikan makanannya', 'Ketika kita rela mempersembahkan apa yang kecil di tangan kita dengan tulus, Tuhan sanggup memakainya menjadi berkat besar bagi banyak orang', 'Yesus tidak bisa menciptakan makanan dari ketiadaan', 'Roti jelai rasanya lebih enak dari roti gandum'], 1, 'Kerelaan berbagi hal kecil di tangan kita saat diserahkan kepada Yesus dapat melipatgandakan mukjizat berkat bagi sesama.');
addQ(2, 'sulit', 'Akar Dosa Kain', 'Tuhan berfirman kepada Kain sebelum membunuh Habel: "Dosa sudah mengintip di depan pintu; ia sangat menggoda engkau, tetapi engkau harus berkuasa atasnya". Makna firman ini adalah ...', ['Manusia tidak bisa menolak godaan berbuat dosa', 'Manusia memiliki tanggung jawab nurani untuk menguasai amarah dan hawa nafsunya sebelum menjadi tindakan nyata yang menghancurkan', 'Dosa hanya berbentuk hewan buas di depan pintu rumah', 'Kain berhak memukul Habel karena merasa lebih tua'], 1, 'Dosa diawali dari rasa iri dan dengki di dalam hati; firman Tuhan menuntut manusia menguasai gejolak emosi destruktif tersebut.');
addQ(2, 'sulit', 'Filosofi Membasuh Kaki', 'Pada zaman Yesus, tugas membasuh kaki para tamu di rumah selalu dikerjakan oleh hamba (budak) yang paling rendah. Mengapa Yesus yang adalah Guru dan Tuhan justru membasuh kaki murid-murid-Nya?', ['Karena tidak ada pelayan di ruangan perjamuan', 'Untuk meruntuhkan konsep kesombongan dunia dan mengajarkan bahwa pemimpin sejati adalah pemimpin yang rela melayani sesama', 'Supaya kaki murid-murid-Nya tidak mengotori lantai ruangan', 'Agar murid-murid memberi Yesus hadiah koin emas'], 1, 'Kepemimpinan pelayan (servant leadership) adalah mahakarya ajaran Kristus: yang terbesar hendaklah menjadi pelayan bagi sesamanya.');
addQ(2, 'sulit', 'Pelajaran Orang Kusta Bersyukur', 'Mengapa Yesus memuji satu orang kusta (seorang Samaria) yang kembali sujud berterima kasih, sedangkan sembilan orang lainnya tidak ditegur di tempat?', ['Karena orang Samaria membawa banyak uang', 'Menunjukkan bahwa banyak orang hanya menginginkan mukjizat kesembuhan jasmani namun lupa memuliakan dan menjalin relasi kasih dengan Sang Sumber Berkat', 'Karena sembilan orang lainnya tersesat di padang belantara', 'Hanya orang Samaria yang boleh disembuhkan'], 1, 'Kisah ini mengkritik sikap manusia yang seringkali mencari pertolongan Tuhan saat susah namun lupa mengucap syukur saat sudah diberkati.');
addQ(2, 'sulit', 'Kaitan Sabat dan Kemanusiaan', 'Ketika orang Farisi memprotes murid Yesus yang memetik bulir gandum pada hari Sabat karena lapar, Yesus menegaskan bahwa ...', ['Hari Sabat boleh dihapus dari kalender', 'Hari Sabat diadakan untuk manusia dan bukan manusia untuk hari Sabat; berbuat kebaikan dan menolong jiwa selalu halal di hari Sabat', 'Murid-murid Yesus kebal dari hukum Taurat', 'Gandum di ladang boleh dicuri kapan saja'], 1, 'Hukum Tuhan dirancang untuk memelihara kehidupan dan kesejahteraan manusia, bukan dijadikan beban legalisme yang mematikan kasih.');
addQ(2, 'sulit', 'Meneladani Rut Menghormati Mertua', 'Keputusan Rut untuk tetap mendampingi Naomi yang miskin dan berduka, padahal ia masih muda dan bisa menikah lagi di negerinya Moab, menunjukkan kasih yang berkarakter ...', ['Kasih pamrih mengharapkan warisan tanah', 'Kasih setia yang rela berkorban (hesed), setia dalam suka maupun duka mendalam', 'Keputusasaan karena tidak memiliki kawan bermain', 'Takut dimarahi oleh keluarga besar Moab'], 1, 'Rut meneladankan kasih hesed (kasih setia tanpa syarat) yang melampaui sekat suku dan penderitaan.');
addQ(2, 'sulit', 'Doa Hana dan Jawaban Tuhan', 'Kisah Hana yang mandul lalu melahirkan Samuel mengajarkan orang beriman bahwa ...', ['Kita harus menangis keras di depan orang banyak saat berdoa', 'Tuhan mendengar doa orang yang patah hati dan berserah penuh dengan integritas iman kepada-Nya', 'Tuhan hanya menyukai anak laki-laki pertama', 'Bait suci adalah tempat untuk menginap selamanya'], 1, 'Ketekunan dan kepasrahan doa Hana membuktikan bahwa tidak ada perkara yang mustahil bagi Tuhan.');
addQ(2, 'sulit', 'Kejujuran di Balik Pintu', 'Mengapa integritas seorang anak kristiani diuji justru saat ia sendirian di kamar dan tidak ada orang tua yang melihat?', ['Karena malaikat Tuhan sedang memegang kamera tersembunyi', 'Karena iman sejati diwujudkan dalam kesadaran bahwa Tuhan Mahahadir (Omnipresent) dan melihat ketulusan hati manusia di tempat tersembunyi', 'Supaya tidak kehilangan uang saku harian', 'Hanya untuk mematuhi peraturan jam belajar sekolah'], 1, 'Integritas berarti berbuat benar di saat tidak ada siapa pun yang memperhatikan, karena hidup di hadapan wajah Allah (Coram Deo).');
addQ(2, 'sulit', 'Makna Menguduskan Sabat di Rumah', 'Bagaimana keluarga kristiani menguduskan hari perhentian (hari Minggu) setelah pulang dari ibadah gereja?', ['Menghabiskan waktu dengan bermain gawai masing-masing tanpa bicara', 'Membangun persekutuan kasih dalam keluarga, makan bersama dengan ucapan syukur, dan beristirahat dengan damai', 'Bekerja lembur mencari uang tambahan', 'Menggosipkan kelemahan pendeta yang berkhotbah'], 1, 'Menguduskan Sabat diteruskan di rumah dengan memelihara damai, istirahat rohani, dan kehangatan relasi keluarga.');
addQ(2, 'sulit', 'Hikmah Bahtera Nuh', 'Mengapa Allah menyelamatkan keluarga Nuh dan berbagai jenis binatang sepasang-sepasang di dalam bahtera?', ['Karena kapal Nuh memiliki teknologi mesin paling canggih', 'Untuk melestarikan kehidupan di bumi dan membuktikan keadilan Allah memelihara orang benar di tengah generasi yang rusak moralnya', 'Supaya Nuh bisa membuka kebun binatang komersial di puncak gunung', 'Karena bumi sudah terlalu sempit untuk manusia'], 1, 'Bahtera Nuh adalah lambang pemeliharaan anugerah keselamatan Allah bagi mereka yang hidup benar dan setia.');
addQ(2, 'sulit', 'Pemberian Tersembunyi', 'Matius 6:3 mengajarkan: "Jika engkau memberi sedekah, janganlah diketahui tangan kirimu apa yang diperbuat tangan kananmu". Maksud ajaran Yesus ini adalah ...', ['Memberi sedekah dengan tangan diikat di belakang punggung', 'Memberi pertolongan dengan ketulusan hati tanpa mencari sanjungan atau memamerkannya kepada publik', 'Hanya bersedekah saat lampu ruangan padam', 'Menolak memberitahu jumlah uang kepada petugas bank'], 1, 'Yesus menentang kemunafikan yang suka memamerkan amal; kebajikan sejati bersumber dari kemurnian kasih di hadapan Bapa.');
addQ(2, 'sulit', 'Makna Kata "Amin"', 'Setiap kali mengakhiri doa pribadi atau doa jemaat di gereja, kita selalu mengucapkan kata "Amin", yang memiliki arti ...', ['"Doa ini sudah selesai dibaca"', '"Sesungguhnya, terjadilah demikian / biarlah kehendak Tuhan terlaksana"', '"Semoga saya mendapat hadiah mainan"', '"Tolong dengarkan suara saya sekarang juga"'], 1, 'Kata "Amin" berasal dari bahasa Ibrani yang berarti sungguh, benar, teguh, atau jadilah demikian menurut kehendak-Mu.');
addQ(2, 'sulit', 'Sikap Menghadapi Teman Pembangkang', 'Jika ada teman di kelompok Sekolah Minggu yang enggan diajak bekerja sama dan suka memicu keributan, sikap bijak kita adalah ...', ['Mengucilkannya dan tidak membiarkannya ikut bernyanyi', 'Menghadapinya dengan sabar, mengajaknya bicara dengan lembut, dan memintakan bantuan guru pendamping', 'Membalas mengejek keluarganya di depan umum', 'Menangis dan mogok mengikuti Sekolah Minggu'], 1, 'Menghadapi kesulitan relasi dengan kesabaran, kelemahlembutan, dan melibatkan pembimbing merupakan penerapan buah Roh.');
addQ(2, 'sulit', 'Menghargai Keberagaman Ciptaan', 'Tuhan menciptakan berbagai macam warna bunga, jenis hewan, dan keberagaman suku manusia di bumi. Pelajaran iman yang dapat kita petik adalah ...', ['Hanya ada satu jenis makhluk yang disayangi Tuhan', 'Keberagaman adalah rancangan agung dan kekayaan ciptaan Tuhan yang harus kita syukuri dan hormati bersama', 'Tuhan sengaja membuat manusia berselisih', 'Bunga mawar lebih mulia daripada bunga melati di hadapan Allah'], 1, 'Keberagaman alam dan manusia memancarkan kemahakuasaan dan keindahan ciptaan Sang Khalik yang harmonis.');
addQ(2, 'sulit', 'Tanggung Jawab Penatalayanan Tubuh', 'Mengapa mengonsumsi makanan bergizi dan menjauhi minuman keras serta rokok merupakan kewajiban iman bagi orang percaya?', ['Supaya tidak dimarahi oleh dokter anak', 'Karena tubuh kita adalah bait Roh Kudus yang ditebus oleh Kristus dan harus dimuliakan dengan hidup sehat dan kudus', 'Hanya agar terlihat atletis di depan teman sebaya', 'Supaya hemat tidak perlu membeli obat'], 1, '1 Korintus 6:19-20 menegaskan tubuh kita adalah bait Roh Kudus; merawat tubuh adalah bagian dari ibadah penatalayanan hidup.');
addQ(2, 'sulit', 'Pengampunan Tanpa Syarat', 'Ketika adik menumpahkan susu ke atas buku gambar kita, sikap batin yang meneladani ajaran kasih Yesus adalah ...', ['Membalas menumpahkan air ke kasur adik', 'Meredakan amarah, memaafkan ketidaksengajaan adik, dan bersama-sama mengelap tumpahan susu tersebut', 'Menyuruh adik dihukum berdiri di teras rumah', 'Menyembunyikan semua makanan adik'], 1, 'Memaafkan kekhilafan saudara dengan lapang dada memadamkan perselisihan dan menumbuhkan rasa aman.');
addQ(2, 'sulit', 'Makna Pelita Alkitab', 'Mazmur menuliskan: "Firman-Mu itu pelita bagi kakiku dan terang bagi jalanku". Fungsi pelita di malam gelap bagi orang yang sedang berjalan adalah ...', ['Membakar rumput kering di tepi jalan', 'Menerangi langkah setapak demi setapak agar terhindar dari lubang bahaya dan tidak tersandung', 'Menyilaukan mata pejalan kaki lain', 'Menjadi tanda bahaya kebakaran hutan'], 1, 'Pelita menerangi langkah hidup manusia agar berjalan di jalan kebenaran dan tidak terperosok ke dalam jerat dosa.');
addQ(2, 'sulit', 'Menghindari Kemarahan Destruktif', 'Efesus 4:26 mengingatkan: "Apabila kamu menjadi marah, janganlah kamu berbuat dosa; janganlah matahari terbenam, sebelum ..."', ['Kamu membalas perbuatan lawanmu', 'Padam amarahmu', 'Semua hutang teman dibayar lunas', 'Kamu memenangkan perdebatan'], 1, 'Firman Tuhan mengajarkan untuk segera menyelesaikan perselisihan dan meredakan amarah sebelum hari berganti malam.');
addQ(2, 'sulit', 'Meneladani Samuel Taat Mendengar', 'Tantangan terbesar bagi anak-anak zaman sekarang untuk mendengar suara bimbingan Tuhan seperti Samuel adalah ...', ['Telinga manusia sekarang lebih kecil dari zaman dahulu', 'Banyaknya kebisingan hiburan gawai dan kesibukan dunia yang mengalihkan perhatian hati dari firman Tuhan', 'Gereja tidak lagi memiliki lonceng menara', 'Alkitab tidak boleh dibaca di rumah'], 1, 'Kebisingan informasi dan godaan gadget sering memadamkan kepekaan rohani anak untuk merenungkan firman Tuhan.');
addQ(2, 'sulit', 'Nilai Persahabatan Sejati', 'Amsal 17:17 mengatakan: "Seorang sahabat menaruh kasih setiap waktu, dan menjadi seorang saudara dalam kesukaran". Ciri sahabat sejati adalah ...', ['Hanya mau berteman saat kita memiliki banyak mainan dan uang jajan', 'Tetap setia mendampingi, menguatkan, dan menolong saat kita tertimpa kesedihan atau musibah', 'Suka menceritakan rahasia kelemahan kita ke orang lain', 'Mengajak kita membolos sekolah bersama'], 1, 'Sahabat sejati diuji dalam masa kesukaran; kasihnya konsisten dan tidak berlandaskan kepentingan materi sepihak.');
addQ(2, 'sulit', 'Syukur Atas Nafas Hidup', 'Mengapa setiap pagi ketika membuka mata kita diajarkan untuk pertama kali mengucap syukur kepada Tuhan?', ['Karena kita berhasil memenangkan perlombaan tidur', 'Karena nafas hidup dan hari yang baru adalah anugerah cuma-cuma dari pemeliharaan kasih setia Tuhan yang tak ternilai harganya', 'Supaya sarapan pagi terasa lebih manis', 'Hanya kebiasaan formalitas sebelum mandi'], 1, 'Setiap detak jantung dan tarikan nafas adalah pemberian cuma-cuma dari Allah yang patut disambut dengan rasa syukur mendalam.');
addQ(2, 'sulit', 'Menyikapi Kegagalan Meraih Juara', 'Ketika regu menyanyi Sekolah Minggu kita hanya meraih juara harapan tiga, sikap yang benar seturut firman Tuhan adalah ...', ['Menangis marah dan membuang piala ke tong sampah', 'Tetap bersyukur telah mempersembahkan pujian terbaik bagi Tuhan dan belajar berlatih lebih giat lagi', 'Menuduh dewan juri bertindak curang', 'Berjanji tidak mau menyanyi di gereja selamanya'], 1, 'Pujian ditujukan bagi kemuliaan Tuhan, bukan keangkuhan piala; menerima hasil dengan lapang dada adalah buah kerendahan hati.');
addQ(2, 'sulit', 'Pemberdayaan Berkat yang Tersisa', 'Setelah Yesus memberi makan lima ribu orang, Ia memerintahkan para murid mengumpulkan roti yang bersisa sebanyak 12 bakul. Hikmah dari perintah ini adalah ...', ['Supaya murid-murid bisa menjual sisa roti ke pasar Yerusalem', 'Mengajarkan agar kita tidak membuang-buang makanan (mubazir) dan menghargai setiap karunia berkat Tuhan dengan bijaksana', 'Hanya untuk menguji kekuatan fisik murid-murid mengangkat bakul', 'Roti yang tersisa harus disimpan untuk tahun depan'], 1, 'Yesus mengajarkan nilai penatalayanan berkat: kelimpahan rezeki tidak boleh disia-siakan atau dibuang sia-sia.');
addQ(2, 'sulit', 'Kasih Tanpa Diskriminasi', 'Bagaimana seorang anak kelas 2 mempraktikkan kasih kepada kawan yang difabel atau memiliki kesulitan berjalan di sekolah?', ['Menatapnya dengan pandangan mengejek sambil berbisik', 'Menemaninya dengan tulus, membantu membawakan tas atau membukakan pintu dengan ramah', 'Melarangnya ikut duduk di teras kelas', 'Mengabaikannya karena tidak bisa diajak lari cepat'], 1, 'Kasih Kristus nyata saat kita merangkul sesama yang berkebutuhan khusus dengan penuh martabat dan penghargaan.');
addQ(2, 'sulit', 'Bahaya Gosip dan Perkataan Sia-sia', 'Amsal memperingatkan bahwa hidup dan mati dikuasai oleh lidah. Apa dampak buruk jika kita suka membicarakan keburukan kawan di belakangnya?', ['Membuat tubuh kita semakin gemuk', 'Menyulut api pertengkaran, merusak tali persahabatan, dan menyebarkan kepedihan di hati kawan', 'Membuat kita terpilih menjadi ketua kelas', 'Semua orang akan menjadi semakin menyukai kita'], 1, 'Perkataan jahat dan gosip melukai jiwa sesama dan mendatangkan dosa di hadapan Tuhan.');
addQ(2, 'sulit', 'Menjadi Saksi Kristus Cilik', 'Bagaimana cara seorang anak kecil dapat menjadi saksi Kristus yang bercahaya di lingkungan tetangganya?', ['Dengan berteriak di jalan menyuruh semua orang ke gereja', 'Melalui tutur kata yang santun, suka menolong, jujur, serta hidup rukun dan damai dengan semua warga sekitar', 'Memamerkan Alkitab bersampul emas di jendela rumah', 'Menolak menyapa tetangga yang berbeda keyakinan'], 1, 'Kesaksian hidup yang paling berkuasa terpancar melalui teladan nyata perbuatan kasih, kejujuran, dan kebaikan hidup sehari-hari.');
addQ(2, 'sulit', 'Makna Doa Sebelum Belajar', 'Mengapa sebelum membuka buku pelajaran di pagi hari kita memohon hikmat dari Tuhan melalui doa?', ['Supaya kita bisa menjawab soal ujian tanpa perlu membaca materi', 'Karena Tuhan adalah Sumber segala hikmat, pengetahuan, dan pemahaman yang sejati', 'Supaya guru tidak berani memberikan pekerjaan rumah', 'Hanya untuk mengisi waktu luang di awal kelas'], 1, 'Amsal 2:6 menyatakan TUHANlah yang memberikan hikmat; memohon pimpinan-Nya membuka pikiran untuk memahami ilmu kebenaran.');
addQ(2, 'sulit', 'Pemaafan Tujuh Puluh Kali Tujuh', 'Ketika Petrus bertanya berapa kali ia harus mengampuni saudaranya yang berbuat salah, Yesus menjawab: bukan sampai tujuh kali, melainkan sampai ...', ['Tujuh puluh kali tujuh kali', 'Sepuluh kali saja', 'Tiga kali lalu balas memukul', 'Tergantung besar kecilnya kesalahan'], 0, 'Tujuh puluh kali tujuh kali adalah ungkapan kiasan bahwa pengampunan orang percaya harus tiada batas dan tidak menyimpan dendam.');
addQ(2, 'sulit', 'Memelihara Kejernihan Hati Nurani', 'Tuhan Yesus bersabda dalam Ucapan Bahagia: "Berbahagialah orang yang suci hatinya, karena mereka akan ..."', ['Melihat Allah', 'Mendapat warisan emas berlimpah', 'Menjadi penguasa imperium Romawi', 'Tidak pernah merasa haus di padang pasir'], 0, 'Matius 5:8 menegaskan orang yang suci hatinya memiliki mata rohani yang peka untuk memandang hadirat dan kehendak Allah.');

addQ(3, 'mudah', 'Daud dan Goliat', 'Gembala muda yang mengalahkan raksasa perkasa Goliat dengan ketapel/umban batu dan iman kepada Allah adalah ...', ['Daud', 'Salomo', 'Samson', 'Saul'], 0, 'Daud mengalahkan Goliat dengan mengandalkan kuasa nama TUHAN semesta alam.');
addQ(3, 'mudah', 'Raksasa Filistin', 'Prajurit raksasa bangsa Filistin yang bertubuh tinggi besar dan menantang barisan tentara Israel bernama ...', ['Goliat', 'Haman', 'Nebukadnezar', 'Balaam'], 0, 'Goliat adalah pendekar raksasa bangsa Filistin dari kota Gat.');
addQ(3, 'mudah', 'Orang Samaria Murah Hati', 'Perumpamaan Yesus tentang orang yang menolong korban perampokan tanpa membeda-bedakan suku dikenal sebagai perumpamaan ...', ['Anak yang Hilang', 'Orang Samaria yang Murah Hati', 'Penabur Benih', 'Domba yang Tersesat'], 1, 'Orang Samaria yang murah hati menolong korban terluka dengan penuh belas kasih.');
addQ(3, 'mudah', 'Kota Perjalanan Samaria', 'Dalam perumpamaan tersebut, orang yang dirampok sedang melakukan perjalanan dari Yerusalem menuju kota ...', ['Nazaret', 'Yerikho', 'Damsyik', 'Tirus'], 1, 'Jalan antara Yerusalem dan Yerikho terkenal terjal dan rawan perampokan pada masa itu.');
addQ(3, 'mudah', 'Kecapi Daud', 'Daud mahir memainkan alat musik petik untuk memuji Tuhan dan menenangkan hati Raja Saul yang gelisah, yaitu alat musik ...', ['Terompet', 'Kecapi', 'Rebana', 'Seruling bambu'], 1, 'Daud pandai memainkan kecapi (harpa) untuk melantunkan puji-pujian Mazmur kepada Allah.');
addQ(3, 'mudah', 'Persembahan Majus Tiga', 'Tiga persembahan berharga yang dibawa oleh orang-orang majus dari Timur untuk bayi Yesus adalah emas, kemenyan, dan ...', ['Intan permata', 'Mur', 'Minyak zaitun', 'Perak murni'], 1, 'Orang majus mempersembahkan emas (lambang raja), kemenyan (lambang imam/ilahiah), dan mur (lambang pengorbanan).');
addQ(3, 'mudah', 'Bintang Betlehem', 'Tanda ajaib di angkasa yang menuntun para majus mencari tempat kelahiran Sang Raja yang baru lahir adalah ...', ['Bintang ajaib yang bersinar terang', 'Bulan purnama merah', 'Awan pelangi', 'Kilatan petir terus-menerus'], 0, 'Bintang Betlehem mendahului dan menuntun para majus tepat di atas tempat bayi Yesus berada.');
addQ(3, 'mudah', 'Penulis Mazmur', 'Kitab Mazmur yang memuat puji-pujian dan doa yang sangat indah di dalam Alkitab sebagian besar ditulis oleh ...', ['Raja Salomo', 'Raja Daud', 'Nabi Elia', 'Nabi Yesaya'], 1, 'Raja Daud dikenal sebagai "pemazmur yang manis dari Israel".');
addQ(3, 'mudah', 'Sahabat Daud', 'Sahabat karib Daud yang merupakan putra sulung Raja Saul dan mengasihi Daud seperti jiwanya sendiri adalah ...', ['Absalom', 'Yonatan', 'Abner', 'Yoab'], 1, 'Yonatan mengikat tali perjanjian persahabatan yang kokoh dan setia dengan Daud.');
addQ(3, 'mudah', 'Setia Perkara Kecil', 'Tuhan Yesus bersabda: "Barangsiapa setia dalam perkara-perkara kecil, ia setia juga dalam perkara-perkara yang ..."', ['Mudah dilupakan', 'Besar', 'Sederhana', 'Tidak penting'], 1, 'Kesetiaan dalam tanggung jawab kecil adalah pintu menuju kepercayaan tugas yang lebih besar.');

addQ(3, 'sedang', 'Imam dan Orang Lewi', 'Ketika seorang musafir tergeletak berlumuran darah dirampok, sikap seorang imam dan orang Lewi yang lewat adalah ...', ['Segera menggendong korban ke rumah sakit terdekat', 'Melewatinya dari seberang jalan dan meninggalkannya tanpa menolong', 'Mengejar para perampok ke tengah hutan', 'Memberikan uang emas kepada korban'], 1, 'Imam dan orang Lewi melalaikan hukum kasih dan memilih menghindar dari seberang jalan.');
addQ(3, 'sedang', 'Minyak dan Anggur Samaria', 'Orang Samaria membersihkan dan membalut luka-luka musafir yang malang itu dengan menuangkan ...', ['Air laut dan garam', 'Minyak dan anggur', 'Cuka asam dan lumpur', 'Madu dan susu'], 1, 'Minyak berfungsi melembutkan luka dan anggur bertindak sebagai antiseptik pembersih luka pada zaman kuno.');
addQ(3, 'sedang', 'Raja Pertama Israel', 'Raja pertama bangsa Israel yang diurapi oleh Nabi Samuel atas kehendak bangsa itu adalah Raja ...', ['Daud', 'Saul', 'Salomo', 'Rehabeam'], 1, 'Saul diurapi oleh Samuel menjadi raja perdana bangsa Israel.');
addQ(3, 'sedang', 'Buah Roh Pertama', 'Dalam Surat Galatia 5:22-23, buah Roh yang pertama kali disebutkan adalah ...', ['Sukacita', 'Kasih', 'Damai sejahtera', 'Kesabaran'], 1, 'Buah Roh diawali oleh Kasih, yang menjadi dasar bagi segenap kebajikan ilahi lainnya.');
addQ(3, 'sedang', 'Jumlah Buah Roh', 'Jumlah aspek Buah Roh yang diajarkan oleh Rasul Paulus dalam Galatia 5:22-23 berjumlah ... sifat.', ['7', '9', '10', '12'], 1, 'Sembilan rasa buah Roh: kasih, sukacita, damai sejahtera, kesabaran, kemurahan, kebaikan, kesetiaan, kelemahlembutan, penguasaan diri.');
addQ(3, 'sedang', 'Buah Roh Kesabaran', 'Penerapan buah Roh "kesabaran" dalam kehidupan murid kelas 3 di sekolah adalah ...', ['Membalas pukulan teman dengan sekuat tenaga', 'Mampu menahan amarah, mengantre tertib, dan tidak mudah tersinggung', 'Membantah perkataan guru saat dinasihati', 'Menyerobot antrean di kantin sekolah'], 1, 'Kesabaran melatih penguasaan diri dan ketenangan jiwa saat menghadapi situasi yang tidak menyenangkan.');
addQ(3, 'sedang', 'Senjata Daud', 'Daud menolak memakai baju perang perunggu dan pedang milik Raja Saul saat maju menghadapi Goliat karena ...', ['Ukurannya terlalu sempit', 'Daud belum terbiasa memakainya dan lebih percaya pada penyertaan nama TUHAN semesta alam', 'Baju zirah tersebut sudah berkarat', 'Daud ingin berlari dengan telanjang kaki'], 1, 'Daud menanggalkan persenjataan berat duniawi dan melangkah dengan iman pada kuasa Allah yang hidup.');
addQ(3, 'sedang', 'Baju Yonatan', 'Sebagai lambang perjanjian kasih persahabatan, Yonatan menanggalkan dan memberikan kepada Daud ...', ['Kuda perang putihnya', 'Jubah kebesarannya, baju perangnya, pedang, panah, dan ikat pinggangnya', 'Mahkota emas ayahnya', 'Seluruh istana Yerusalem'], 1, 'Yonatan menyerahkan perlengkapan ksatrianya kepada Daud sebagai tanda kerelaan dan ikatan kasih persaudaraan.');
addQ(3, 'sedang', 'Benih di Tanah Subur', 'Dalam Perumpamaan Seorang Penabur, benih yang jatuh di tanah yang baik akan menghasilkan buah ...', ['Sepuluh kali lipat', 'Tiga puluh kali lipat, enam puluh kali lipat, bahkan seratus kali lipat', 'Semuanya dimakan oleh burung pipit', 'Mati mengering terbakar matahari'], 1, 'Hati yang mendengar, mengerti, dan melakukan firman menghasilkan buah kehidupan yang berlipat ganda.');
addQ(3, 'sedang', 'Menjaga Mata Air', 'Tindakan memelihara ciptaan Tuhan di lingkungan alam sekitar dapat diwujudkan dengan ...', ['Membuang sampah plastik dan limbah ke dalam sungai', 'Menjaga kebersihan selokan dan tidak mencemari sumber mata air bersih', 'Menebang pohon lindung di bukit secara liar', 'Meracuni ikan-ikan kecil di danau'], 1, 'Air adalah anugerah kehidupan ciptaan Allah yang wajib dipelihara kejernihannya bagi sesama makhluk.');
addQ(3, 'sedang', 'Kejujuran Menemukan Barang', 'Bila kita menemukan sebuah jam tangan mewah terjatuh di halaman sekolah, tindakan integritas seorang anak kristiani adalah ...', ['Menyembunyikannya ke dalam kotak pensil sendiri', 'Segera menyerahkannya kepada bapak/ibu guru piket agar diumumkan kepada pemiliknya', 'Menjual jam tersebut kepada orang di luar sekolah', 'Meninggalkannya begitu saja agar diinjak orang'], 1, 'Integritas menuntun kita mengembalikan hak orang lain yang bukan milik kita.');
addQ(3, 'sedang', 'Yesus Redakan Badai', 'Ketika perahu para murid di Danau Galilea diterpa gelombang ombak dahsyat, Tuhan Yesus meredakan badai itu dengan berfirman: ...', ['"Ayo mendayung lebih cepat!"', '"Diam! Tenanglah!"', '"Lompatlah ke dalam air!"', '"Bangunlah kapal baru!"'], 1, 'Hanya dengan firman: "Diam! Tenanglah!", angin badai pun reda dan danau menjadi teduh sunyi.');
addQ(3, 'sedang', 'Buritan Kapal', 'Saat angin taufan mengamuk di Danau Galilea, Tuhan Yesus sedang berada di bagian buritan kapal sedang ...', ['Membaca gulungan kitab suci', 'Tidur beralaskan bantal', 'Makan malam bersama para nelayan', 'Memperbaiki layar yang robek'], 1, 'Yesus tidur dengan tenang, menunjukkan kuasa damai yang mengatasi segala kecemasan alam semesta.');
addQ(3, 'sedang', 'Pohon Ara Zakheus', 'Zakheus yang memiliki tubuh pendek memanjat pohon ara (sikomodorus) dengan tujuan agar ...', ['Bisa bersembunyi dari kejaran polisi Romawi', 'Dapat melihat wajah Tuhan Yesus yang sedang berjalan melewati kerumunan orang banyak', 'Bisa memetik buah ara untuk sarapan', 'Dapat melempari orang dengan biji ara'], 1, 'Kerinduan hati Zakheus melihat Yesus mendorongnya mengesampingkan rasa gengsi dengan memanjat pohon.');
addQ(3, 'sedang', 'Pekerjaan Zakheus', 'Sebelum mengalami perjumpaan yang mengubah hidupnya dengan Yesus, pekerjaan Zakheus di kota Yerikho adalah sebagai ...', ['Nelayan penangkap ikan', 'Kepala pemungut cukai yang kaya raya', 'Prajurit pengawal istana', 'Tukang pembuat tenda'], 1, 'Zakheus adalah kepala pemungut cukai yang sering dicap sebagai orang berdosa oleh masyarakat.');
addQ(3, 'sedang', 'Resolusi Zakheus', 'Tanda nyata pertobatan sejati Zakheus setelah menyambut Yesus di rumahnya adalah kerelaannya untuk ...', ['Memberikan separuh hartanya kepada orang miskin dan mengembalikan empat kali lipat jika pernah memeras orang', 'Membangun patung perunggu di gerbang kota', 'Pindah rumah ke luar negeri', 'Menutup seluruh kantor cukai di kotanya'], 0, 'Pertobatan sejati berbuah pada perbaikan moral, keadilan materi, dan kemurahan hati kepada kaum dhuafa.');
addQ(3, 'sedang', 'Keadilan dalam Permainan', 'Contoh perilaku adil saat bermain sepak bola di lapangan sekolah adalah ...', ['Menunjuk diri sendiri selalu menjadi kapten tanpa persetujuan tim', 'Mematuhi peraturan permainan dan menerima keputusan wasit dengan jujur', 'Menjegal kaki lawan secara sengaja saat wasit lengah', 'Mogok bermain jika tim lawan mencetak gol'], 1, 'Sportivitas dan kepatuhan pada aturan adalah wujud nyata keadilan dan kejujuran.');
addQ(3, 'sedang', 'Jawaban Lemah Lembut', 'Amsal 15:1 menegaskan: "Jawaban yang lemah lembut meredakan ..., tetapi perkataan yang pedas membangkitkan amarah".', ['Kegeraman / kemarahan', 'Sukacita pesta', 'Kelaparan di musim kering', 'Rasa kantuk'], 0, 'Kata-kata yang lembut mampu menyejukkan hati yang panas dan memulihkan suasana damai.');
addQ(3, 'sedang', 'Merawat Hewan Peliharaan', 'Jika kita memelihara seekor anjing atau kucing di rumah, kewajiban kita sebagai anak Tuhan adalah ...', ['Mengurungnya di kandang sempit tanpa makanan', 'Memberinya makan dan minum teratur serta merawat kesehatannya dengan kasih', 'Melempari dengan batu jika hewan itu bersuara', 'Membiarkannya kehujanan di malam hari'], 1, 'Orang benar memperhatikan hidup hewan piaraannya (Amsal 12:10).');
addQ(3, 'sedang', 'Menolak Ajakan Curang', 'Bila ada teman yang mengajak kita berbisik-bisik bertukar jawaban saat ujian semester, respons kristiani kita adalah ...', ['Menerima ajakannya agar mendapat nilai seratus bersama', 'Menolak dengan tegas namun santun dan mengajak teman itu percaya pada kemampuan sendiri serta pimpinan Tuhan', 'Meminta bayaran uang sebelum memberi jawaban', 'Melaporkan dengan berteriak di tengah ruang ujian'], 1, 'Menolak kompromi kecurangan dengan santun membuktikan keteguhan integritas iman.');

addQ(3, 'sulit', 'Analisis Iman Daud vs Goliat', 'Dalam 1 Samuel 17:45, Daud berkata kepada Goliat: "Engkau mendatangi aku dengan pedang dan tombak dan lembing, tetapi aku mendatangi engkau dengan nama TUHAN semesta alam". Apa makna terdalam dari ucapan iman Daud tersebut?', ['Daud mengancam Goliat dengan mantra sihir bangsa Israel', 'Daud menaruh keyakinan mutlak bukan pada kekuatan fisik atau senjata duniawi, melainkan pada kedaulatan dan kuasa Allah yang hidup', 'Daud merasa dirinya lebih sakti daripada seluruh prajurit Israel', 'Daud ingin memamerkan kemampuannya melempar batu ketapel'], 1, 'Kemenangan Daud membuktikan bahwa kuasa iman yang mengandalkan Allah sanggup meruntuhkan raksasa ketakutan sebesar apa pun.');
addQ(3, 'sulit', 'Konsep Sesamaku Manusia', 'Dalam Perumpamaan Orang Samaria yang Murah Hati, siapakah yang dimaksud dengan "sesamaku manusia" menurut pengajaran Tuhan Yesus?', ['Hanya orang-orang yang berasal dari suku dan agama yang sama dengan kita', 'Siapa saja manusia yang membutuhkan pertolongan kasih, melampaui sekat suku, ras, kebangsaan, dan latar belakang agama', 'Orang yang kaya raya dan terpandang di masyarakat', 'Sahabat dekat yang sering membelikan kita hadiah'], 1, 'Yesus merombak definisi sempit eksklusivisme; sesamaku manusia adalah setiap orang yang kita jumpai dalam penderitaan yang membutuhkan uluran kasih kita.');
addQ(3, 'sulit', 'Pertobatan Radikal Zakheus', 'Mengapa perjumpaan dengan Yesus di rumahnya mampu mengubah hati Zakheus yang serakah menjadi seorang yang sangat dermawan?', ['Karena Yesus mengancam akan membakar seluruh harta bendanya', 'Karena Zakheus merasakan kasih, pengampunan, dan penerimaan tanpa syarat dari Yesus yang menyentuh nuraninya hingga melahirkan pembaruan hidup', 'Karena Zakheus ingin mencalonkan diri menjadi bupati Yerikho', 'Supaya rakyat Yerikho tidak lagi membenci pekerjaannya'], 1, 'Kasih karunia dan penerimaan Kristus memerdekakan jiwa Zakheus dari jerat ketamakan materi menuju kemurahan hati.');
addQ(3, 'sulit', 'Empat Jenis Tanah Hati Manusia', 'Dalam Perumpamaan Penabur, benih yang jatuh di tengah semak duri melambangkan orang yang mendengar firman Tuhan, namun kemudian firman itu terhimpit mati oleh ...', ['Kekurangan air dan pupuk tanaman', 'Kekhawatiran duniawi, tipu daya kekayaan, dan kenikmatan hidup yang memadamkan pertumbuhan iman', 'Burung-burung gagak di angkasa', 'Batu-batu cadas yang terjal'], 1, 'Semak duri adalah gambaran kecemasan dunia dan cinta kekayaan yang mencekik pertumbuhan firman dalam kehidupan sehari-hari.');
addQ(3, 'sulit', 'Makna Mengatasi Badai Kehidupan', 'Kisah Yesus meredakan angin ribut di danau Danau Galilea mengajarkan orang percaya saat menghadapi "badai" persoalan hidup yang berat untuk ...', ['Melompat keluar dari perahu dan menyerah kalah', 'Tidak panik atau berputus asa, melainkan mengarahkan pandangan iman kepada kehadiran Yesus yang berkuasa memberikan damai sejahtera', 'Menyalahkan nahkoda perahu yang kurang waspada', 'Meminta pertolongan kepada dukun peramal cuaca'], 1, 'Ketenangan Yesus di tengah badai menenangkan jiwa kita bahwa bersama Kristus dalam perahu kehidupan kita tidak akan binasa.');
addQ(3, 'sulit', 'Etika Persahabatan Daud Yonatan', 'Yonatan adalah putra mahkota yang berhak mewarisi takhta ayahnya, Raja Saul. Mengapa Yonatan justru melindungi Daud dan rela Daud menjadi raja pengganti ayahnya?', ['Karena Yonatan malas memimpin kerajaan Israel', 'Karena Yonatan tunduk pada kehendak Allah dan memiliki kasih persahabatan sejati yang tulus tanpa iri hati maupun ambisi kekuasaan pribadi', 'Karena Daud berjanji memberi Yonatan emas berlimpah', 'Karena Saul memerintahkan Yonatan menyerahkan takhta'], 1, 'Yonatan meneladankan ketulusan persahabatan agung yang menomorsatukan rencana Allah di atas ambisi kekuasaan fana.');
addQ(3, 'sulit', 'Tantangan Legalitas Imam dan Lewi', 'Mengapa seorang imam dan orang Lewi dalam perumpamaan Orang Samaria memilih lewat dari seberang jalan dan menolak menolong korban perampokan?', ['Karena mereka tidak membawa kotak P3K', 'Diduga karena kekhawatiran hukum upacara kenajisan jika menyentuh mayat, yang membutakan mata nurani mereka terhadap hukum kasih yang terutama', 'Karena mereka sedang terburu-buru menghadiri pesta pernikahan di Yerikho', 'Karena mereka mengira korban sedang berpura-pura tidur'], 1, 'Kritik Yesus menyoroti ketaatan aturan lahiriah tanpa belas kasihan adalah kemunafikan yang bertentangan dengan kehendak Allah.');
addQ(3, 'sulit', 'Pengorbanan Tiga Orang Majus', 'Perjalanan panjang orang-orang majus dari Timur melintasi padang pasir berbahaya untuk menyembah bayi Yesus mengajarkan nilai iman berupa ...', ['Wisata belanja barang antik di tanah Yudea', 'Pencarian kebenaran sejati dengan ketekunan, pengorbanan waktu dan materi, serta penyerahan persembahan terbaik bagi Sang Raja Damai', 'Mencari sekutu militer baru bagi kerajaan Timur', 'Mengumpulkan cerita legenda kuno untuk buku sastra'], 1, 'Para majus mewakili bangsa-bangsa bukan Yahudi yang mencari dan menyembah Kristus dengan ketulusan dan pengorbanan bakti.');
addQ(3, 'sulit', 'Buah Roh Penguasaan Diri di Era Gadget', 'Bagaimana seorang siswa kelas 3 mengamalkan buah Roh "penguasaan diri" dalam penggunaan gawai (smartphone) di rumah?', ['Bermain game online sampai larut malam tanpa menghiraukan PR', 'Mampu membatasi waktu layar secara disiplin, memprioritaskan belajar, istirahat cukup, dan menyaring konten yang sehat', 'Menyembunyikan gawai di bawah bantal agar tidak disita ibu', 'Menolak berbicara dengan orang tua jika kuota internet habis'], 1, 'Penguasaan diri adalah benteng pertahanan moral agar tidak diperbudak oleh kecanduan teknologi dan hiburan duniawi.');
addQ(3, 'sulit', 'Mandat Budaya Merawat Bumi', 'Dalam Kitab Kejadian 2:15, manusia ditempatkan di bumi untuk "mengusahakan dan memeliharanya". Dalam perspektif iman kristiani, tindakan membuang sampah sembarangan dan merusak hutan merupakan perbuatan ...', ['Biasa saja karena hutan tumbuh kembali sendiri', 'Dosa pengkhianatan terhadap mandat penatalayanan (stewardship) yang dipercayakan Allah kepada manusia atas ciptaan-Nya', 'Perbuatan wajar untuk pembangunan ekonomi modern', 'Hanya pelanggaran hukum perda kota tanpa kaitan dengan iman'], 1, 'Merawat lingkungan adalah tanggung jawab moral-spiritual sebagai mandataris Allah di bumi.');
addQ(3, 'sulit', 'Analisis Kesetiaan Daud di Padang Gurun', 'Ketika Saul mengejar Daud untuk membunuhnya dan Daud memiliki dua kali kesempatan emas membunuh Saul di dalam gua, mengapa Daud menolak membunuh Saul?', ['Karena Daud tidak membawa pedang tajam', 'Karena Daud takut kepada Allah dan sangat menghormati Saul sebagai "orang yang diurapi TUHAN"', 'Karena Daud takut dikeroyok oleh prajurit Saul', 'Karena Daud ingin memperpanjang masa persembunyiannya'], 1, 'Daud menolak memakai cara-cara berdosa atau balas dendam, dan memilih menyerahkan perkaranya ke dalam penghakiman adil Allah.');
addQ(3, 'sulit', 'Kritik Terhadap Sikap Bersungut-sungut', 'Bangsa Israel yang dibebaskan dari perbudakan Mesir sering bersungut-sungut di padang gurun karena makanan dan air. Akibat dari sikap bersungut-sungut tersebut adalah ...', ['Mereka langsung sampai ke tanah Kanaan dalam tiga hari', 'Hati menjadi tumpul, tidak dapat melihat kebaikan pemeliharaan Tuhan, dan mendatangkan murka Allah', 'Mendapat roti manna dua kali lipat lebih banyak', 'Raja Firaun meminta mereka kembali ke istana'], 1, 'Bersungut-sungut merusak iman dan menutup mata rohani dari berkat pemeliharaan Tuhan.');
addQ(3, 'sulit', 'Mutiara Pengampunan Salib', 'Perkataan pertama Tuhan Yesus dari atas kayu salib bagi para prajurit dan orang-orang yang menyalibkan-Nya adalah ...', ['"Lihatlah pembalasan api dari surga akan turun atas kalian"', '"Ya Bapa, ampunilah mereka, sebab mereka tidak tahu apa yang mereka perbuat"', '"Turunkanlah Aku dari salib ini sekarang juga"', '"Aku tidak akan pernah memaafkan bangsa ini"'], 1, 'Lukas 23:34 merekam puncak kasih pengampunan Kristus yang mendoakan orang-orang yang menyiksa-Nya.');
addQ(3, 'sulit', 'Makna Iman Sebutir Biji Sesawi', 'Yesus bersabda: "Sekiranya kamu mempunyai iman sebesar biji sesawi saja, kamu dapat berkata kepada gunung ini: Pindahlah... maka gunung ini akan pindah". Makna perumpamaan ini adalah ...', ['Kita harus membawa bibit sesawi ke mana pun kita pergi', 'Kualitas iman yang hidup dan bersandar penuh pada kemahakuasaan Allah sanggup melakukan perkara-perkara mustahil melampaui logika manusiawi', 'Orang beriman harus mampu memindahkan batu-batu gunung secara fisik', 'Iman diukur dari ukuran fisik kepala manusia'], 1, 'Biji sesawi sangat kecil namun memiliki daya hidup; iman yang sejati kepada Allah sanggup menembus kemustahilan.');
addQ(3, 'sulit', 'Etika Memberi Nasihat Antar Kawan', 'Bila teman kita di Sekolah Minggu melakukan perbuatan yang salah, cara menegur yang diajarkan dalam Matius 18 adalah ...', ['Mengumumkannya di mikrofon Sekolah Minggu agar dia merasa malu', 'Menemuinya dan menegurnya secara pribadi di bawah empat mata dengan kasih dan kelemahlembutan', 'Membicarakannya di grup obrolan media sosial', 'Memusuhinya dan mengajak kawan lain menjauhinya'], 1, 'Matius 18:15 mengajarkan peneguran secara pribadi empat mata demi memenangkan kembali hati saudara tersebut.');
addQ(3, 'sulit', 'Hikmah Mukjizat Perkawinan di Kana', 'Mukjizat pertama yang dilakukan Yesus di Kana dengan mengubah air menjadi anggur manis terbaik menunjukkan bahwa ...', ['Yesus gemar menghadiri pesta hura-hura', 'Yesus peduli pada kebutuhan dan sukacita hidup keluarga manusia serta menyatakan kemuliaan kuasa-Nya agar murid-murid-Nya percaya', 'Air sumur di Kana memiliki rasa anggur alami', 'Tuan pesta tidak memiliki uang untuk membeli minuman'], 1, 'Yohanes 2:11 mencatat ini adalah tanda pertama yang menyatakan kemuliaan Yesus dan memimpin murid-murid-Nya kepada iman.');
addQ(3, 'sulit', 'Karakter Orang Benar Pohon Berakar', 'Mazmur 1 mengibaratkan orang benar seperti pohon yang ditanam di tepi aliran air, yang menghasilkan buahnya pada musimnya dan ...', ['Daunnya cepat gugur kekeringan', 'Daunnya tidak layu dan apa saja yang diperbuatnya berhasil', 'Batangnya berduri tajam melukai orang', 'Akarnya mudah tumbang tertiup angin sepoi-sepoi'], 1, 'Orang benar yang merenungkan firman TUHAN siang dan malam berakar kuat dalam anugerah dan menghasilkan buah kebaikan.');
addQ(3, 'sulit', 'Perlawanan Terhadap Kesombongan Diri', 'Amsal 16:18 mengingatkan: "Kecongkakan mendahului kehancuran, dan tinggi hati mendahului ..."', ['Kemakmuran emas', 'Kejatuhan', 'Kemenangan besar', 'Kemuliaan tahta'], 1, 'Kesombongan adalah jerat kehancuran; kerendahan hati mendahului kehormatan di hadapan Tuhan.');
addQ(3, 'sulit', 'Makna Menyimpan Harta di Surga', 'Yesus menasihatkan: "Kumpulkanlah bagimu harta di surga; di surga ngengat dan karat tidak merusakkannya dan pencuri tidak membongkar serta mencurinya". Maksud mengumpulkan harta di surga adalah ...', ['Menyimpan perhiasan emas di bawah bantal tempat tidur', 'Memperkaya hidup dengan iman, perbuatan kasih, kebajikan kepada kaum miskin, dan kesetiaan melayani Tuhan', 'Membeli tanah di dekat bukit zaitun', 'Menolak memiliki uang belanja untuk sekolah'], 1, 'Harta surgawi adalah kekayaan spiritual dan kebajikan kekal yang tidak dapat dirusak oleh waktu dan materi fana.');
addQ(3, 'sulit', 'Sikap Menghadapi Tekanan Teman Sebaya', 'Ketika teman-teman sekelas mengajak mengejek seorang guru yang tegas, sikap anak beriman yang benar adalah ...', ['Ikut mengejek agar tidak dianggap sok suci oleh teman', 'Berani berdiri teguh pada kebenaran, menolak ajakan tersebut dengan sopan, dan tidak ikut-ikutan berbuat jahat', 'Merekam video teman-teman lalu memeras mereka', 'Menertawakan dari kejauhan'], 1, 'Keluaran 23:2 memerintahkan: "Janganlah engkau turut-turut kebanyakan orang melakukan kejahatan".');
addQ(3, 'sulit', 'Kisah Salomo Memohon Hikmat', 'Ketika Tuhan menampakkan diri dalam mimpi dan menyuruh Salomo meminta apa saja yang ia kehendaki, Salomo tidak meminta umur panjang atau kekayaan, melainkan meminta ...', ['Pasukan kuda perang terkuat di dunia', 'Hati yang faham menimbang perkara (hikmat kebijaksanaan) untuk memimpin dan menghakimi umat Tuhan', 'Mahkota bertabur permata rubi', 'Istana yang terbuat dari emas murni'], 1, '1 Raja-raja 3 mencatat Salomo memohon hikmat kebijaksanaan untuk melayani dan menimbang keadilan bagi rakyatnya.');
addQ(3, 'sulit', 'Teladan Daud Mengakui Dosa', 'Ketika ditegur oleh Nabi Natan atas dosanya, sikap Daud yang membedakannya dari Raja Saul adalah ...', ['Membela diri dan menyalahkan orang lain', 'Segera bersujud mengakui kesalahannya dengan penyesalan mendalam dan memohon pengampunan Allah (Mazmur 51)', 'Menjebloskan Nabi Natan ke dalam penjara bawah tanah', 'Menolak mendengarkan firman teguran Tuhan'], 1, 'Daud memiliki kerendahan hati untuk bertobat sungguh-sungguh saat ditegur oleh firman kebenaran.');
addQ(3, 'sulit', 'Makna "Tangan Kanan Memberi Tangan Kiri Tidak Tahu"', 'Penerapan nasihat Yesus tentang memberi sedekah secara tersembunyi bagi seorang pelajar adalah ...', ['Menaruh uang infak dengan menutup mata rapat-rapat', 'Menolong teman yang kekurangan secara diam-diam tanpa perlu menceritakannya ke semua teman kelas untuk dipuji', 'Menolak menolong jika ada orang lain di dekatnya', 'Menyembunyikan dompet di dalam sepatu'], 1, 'Kebajikan sejati tidak mencari panggung kepopuleran; motivasinya murni menyenangkan hati Allah.');
addQ(3, 'sulit', 'Pemberian Berkat Lewat Kelemahan', 'Dalam 2 Korintus 12:9 Tuhan berfirman kepada Paulus: "Cukuplah kasih karunia-Ku bagimu, sebab justru dalam kelemahanlah kuasa-Ku menjadi sempurna". Makna dari firman ini adalah ...', ['Tuhan hanya menyukai orang yang sakit parah', 'Ketika kita menyadari keterbatasan diri dan bersandar penuh pada Allah, kuasa dan anugerah Tuhan dinyatakan dengan luar biasa', 'Kita tidak perlu berlatih olahraga agar tetap lemah', 'Kelemahan fisik adalah tanda kutukan Tuhan'], 1, 'Kesadaran akan ketidakberdayaan diri memimpin manusia bersandar seutuhnya pada kekuatan adikodrati Allah.');
addQ(3, 'sulit', 'Analisis Ketulusan Doa Janda Miskin', 'Yesus memuji persembahan dua peser janda miskin lebih banyak dari persembahan orang kaya karena ...', ['Uang dua peser terbuat dari logam mulia murni', 'Orang kaya memberi dari kelimpahannya, sedangkan janda itu memberi dari kekurangannya, seluruh nafkah yang dimilikinya dengan iman total', 'Janda itu memasukkan uang dengan suara denting paling keras', 'Yesus hanya menyukai persembahan dalam pecahan kecil'], 1, 'Tuhan tidak menilai nominal angka lahiriah, melainkan besarnya pengorbanan dan ketulusan hati yang berserah.');
addQ(3, 'sulit', 'Menjaga Hubungan Damai Antar Etnis', 'Tuhan menciptakan manusia dari berbagai suku bangsa di muka bumi. Bagaimana pelajar kristiani membina kerukunan di tengah sekolah yang multikultural?', ['Membentuk geng khusus satu suku untuk menjaga keamanan kelompok', 'Menghargai tradisi teman, saling mengenal budaya, dan mengikat tali persahabatan yang tulus tanpa diskriminasi', 'Mengharuskan semua teman berbicara menggunakan bahasa daerah kita', 'Menghindari kerja kelompok dengan anak dari luar daerah'], 1, 'Kasih Kristus meruntuhkan tembok pemisah etnis dan mempersatukan semua anak bangsa dalam damai dan saling menghargai.');
addQ(3, 'sulit', 'Hikmah Menjadi Garam Dunia', 'Yesus menyebut murid-murid-Nya sebagai "garam dunia". Fungsi garam yang harus dipantulkan oleh karakter orang beriman adalah ...', ['Membuat makanan menjadi sangat asin dan pahit', 'Mencegah kebusukan moral, memberi cita rasa damai, dan membawa pengaruh kebaikan di lingkungan sekitar', 'Hanya dipakai di dapur saat memasak', 'Membuat orang lain merasa haus terus-menerus'], 1, 'Garam mencegah pembusukan dan memberi rasa sedap; orang percaya dipanggil mencegah kejahatan dan membawa kebaikan.');
addQ(3, 'sulit', 'Perlawanan Terhadap Sikap Menghakimi', 'Matius 7:1-3 mengingatkan kita untuk tidak menghakimi sesama: "Mengapakah engkau melihat selumbar di mata saudaramu, sedangkan ... di dalam matamu tidak engkau ketahui?"', ['Kacamata hitam', 'Balok', 'Batu kerikil', 'Kotoran debu'], 1, 'Yesus mengkritik mereka yang sibuk mencari kesalahan kecil orang lain sementara dosa besar dalam dirinya sendiri diabaikan.');
addQ(3, 'sulit', 'Ketaatan Melebihi Korban Sembelihan', 'Nabi Samuel menegaskan kepada Saul: "Mendengarkan lebih baik dari pada ..., dan memperhatikan lebih baik dari pada lemak domba-domba jantan".', ['Menangis di kemah', 'Korban sembelihan', 'Menyanyi di padang', 'Berdiam diri'], 1, '1 Samuel 15:22: Allah lebih menghendaki ketaatan hati yang tulus daripada sekadar ritual korban persembahan lahiriah tanpa kepatuhan.');
addQ(3, 'sulit', 'Sikap Menghargai Kehidupan', 'Alkitab menegaskan bahwa hidup manusia adalah suci sejak dalam kandungan. Oleh karena itu, sikap yang wajib dijunjung tinggi adalah ...', ['Melindungi, menghormati, dan merawat hak hidup setiap manusia tanpa kekerasan', 'Boleh melukai orang lain jika kita sedang merasa kesal', 'Menganggap nyawa orang miskin kurang berharga', 'Menyerahkan perlindungan nyawa hanya kepada aparat polisi'], 0, 'Kehidupan adalah karunia suci dari Allah; setiap insan wajib menghormati martabat dan perlindungan jiwa sesama.');

fs.writeFileSync(path.join(__dirname, '..', 'generators', 'agama_kristen.json'), JSON.stringify(kristenQuestions, null, 2), 'utf8');
console.log(`Saved ${kristenQuestions.length} Agama Kristen questions (Kelas 1-3).`);
